head.b:skin:
:root{color-scheme:dark;--bg:#0e0c0a;--fg:#e8e1d5;--mute:#8b8277;--line:rgba(232,225,213,.16);--g:clamp(1.25rem,4vw,3.5rem);
--serif:'Cormorant Garamond','Iowan Old Style',Georgia,serif;--sans:'Hanken Grotesk',system-ui,sans-serif;--ease:cubic-bezier(.16,1,.3,1);
box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
*,*::before,*::after{box-sizing:inherit}
html{scroll-behavior:smooth;scroll-padding-top:env(safe-area-inset-top,0px);background:var(--bg)}
body{margin:0;background:var(--bg);color:var(--fg);font:400 1rem/1.7 var(--sans);letter-spacing:.005em;-webkit-font-smoothing:antialiased}
::selection{background:var(--fg);color:var(--bg)}
a{color:inherit;text-decoration:none}
a:focus-visible{outline:1px solid var(--fg);outline-offset:6px}
img{display:block}
/* empat ukuran saja: display, judul, teks, label */
.d{font:400 clamp(2.75rem,7.2vw,6.25rem)/1.02 var(--serif);letter-spacing:-.015em}
.t{font:400 clamp(1.5rem,2.4vw,2rem)/1.2 var(--serif)}
.l{font:500 .75rem/1.4 var(--sans);letter-spacing:.16em;text-transform:uppercase;color:var(--mute)}
em{font-style:italic}
.wrap{padding-inline:var(--g);max-width:88rem;margin-inline:auto}
header{position:fixed;inset:0 0 auto;z-index:5;display:flex;justify-content:space-between;align-items:center;padding:1.25rem var(--g);padding-top:calc(1.25rem + env(safe-area-inset-top,0px));background:linear-gradient(var(--bg),transparent)}
header img{height:1.9rem;width:auto;filter:invert(1);opacity:.92}
:root[data-theme=light]{color-scheme:light;--bg:#f1ede5;--fg:#1c1814;--mute:#766d62;--line:rgba(28,24,20,.2)}
html,body{transition:background-color .7s var(--ease),color .7s var(--ease)}
:root[data-theme=light] header img{filter:none}
/* ikon garis tipis, jam digital, pilihan latar */
.tools{display:flex;align-items:center;gap:.25rem}
.tools svg{width:1.25rem;height:1.25rem;fill:none;stroke:currentColor;stroke-width:1;stroke-linecap:round;stroke-linejoin:round}
.ic{display:grid;place-items:center;width:2rem;height:2.25rem;opacity:.7;transition:opacity .5s var(--ease),transform .5s var(--ease)}
.ic:hover,.ic[aria-pressed=true]{opacity:1}
.ic:hover{transform:translateY(-1px)}
.ic[aria-pressed=false]{opacity:.4}
.ic[aria-pressed=false]:hover{opacity:.9}
button.ic{background:none;border:0;color:inherit;cursor:pointer;padding:0}
.sep{width:1px;height:1rem;background:var(--line);margin-inline:.5rem}
#clk{font-variant-numeric:tabular-nums;margin-right:.75rem;white-space:nowrap}
#clk .tz{color:var(--mute)}
@media(max-width:32rem){#clk .sec{display:none}#clk{margin-right:.25rem}}
@media(max-width:26rem){#clk .tz{display:none}}
@media(min-width:40rem){.ic{width:2.25rem}.sep{margin-inline:.75rem}}
.tg{position:relative}
.tg svg{position:absolute;left:50%;top:50%;margin:-.625rem 0 0 -.625rem;transition:transform .9s var(--ease),opacity .6s var(--ease)}
.tg .moon{opacity:1;transform:none}
.tg .sun{opacity:0;transform:rotate(-90deg) scale(.4)}
:root[data-theme=light] .tg .moon{opacity:0;transform:rotate(90deg) scale(.4)}
:root[data-theme=light] .tg .sun{opacity:1;transform:none}
.tg:active svg{transform:scale(.88)}
header>a{flex:none}.tools{min-width:0}
@media(max-width:40rem){header{padding-inline:1rem}header img{height:1.55rem}.tools{gap:0}.work a{grid-template-columns:2rem 1fr}.work .m{grid-column:2;text-align:left}.hero .foot{flex-direction:column;gap:.5rem}section{padding-block:5rem}.contact .meta{gap:.75rem 1.75rem}footer{flex-direction:column}}
@media(max-width:23rem){#clk{display:none}}
section{padding-block:clamp(6rem,14vw,12rem)}
.hero{min-height:100svh;display:flex;flex-direction:column;justify-content:flex-end;padding-bottom:clamp(3rem,7vw,6rem)}
.hero p.l{margin:0 0 2.25rem}
.hero .d{margin:0;max-width:15ch}
.hero .foot{display:flex;justify-content:space-between;gap:2rem;margin-top:clamp(3rem,8vw,7rem)}
.rule{height:1px;background:var(--line);transform:scaleX(0);transform-origin:left;transition:transform 1.6s var(--ease)}
.rule.in{transform:none}
.cols{display:grid;gap:2.5rem var(--g);grid-template-columns:1fr}
@media(min-width:56rem){.cols{grid-template-columns:minmax(0,4fr) minmax(0,8fr)}}
/* karya: baris tipografi */
.work a{display:grid;grid-template-columns:2.5rem 1fr auto;align-items:baseline;gap:1rem;padding-block:1.6rem;border-top:1px solid var(--line);transition:padding .8s var(--ease)}
.work li:last-child a{border-bottom:1px solid var(--line)}
.work .n{font-variant-numeric:tabular-nums;color:var(--mute);font-size:.8125rem}
.work .t{transition:transform .8s var(--ease),opacity .6s}
.work a:hover .t,.work a.hv .t{transform:translateX(.75rem)}
.work ul:hover a:not(:hover) .t{opacity:.45}
.work ul.hv-on a:not(.hv) .t{opacity:.45}
.work .m{color:var(--mute);font-size:.875rem;text-align:right}
@media(max-width:55.99rem){.work a{grid-template-columns:2.5rem 1fr;gap:.25rem 1rem}.work .m{grid-column:2;text-align:left}}
@media(max-width:40rem){.work a{grid-template-columns:2rem 1fr}}
/* pratinjau gambar saat hover: memuat dengan garis progres, lalu terbuka */
#pv{position:fixed;left:0;top:0;z-index:4;width:min(22vw,19rem);aspect-ratio:4/5;pointer-events:none;opacity:0;overflow:hidden;border:1px solid var(--line);background:rgba(128,128,128,.07);transition:opacity .45s var(--ease);will-change:transform}
#pv.on{opacity:1}
#pv .im{position:absolute;inset:0;background-size:cover;background-position:center;clip-path:inset(100% 0 0 0);transform:scale(1.1);transition:clip-path 1s var(--ease),transform 1.5s var(--ease)}
#pv.ready .im{clip-path:inset(0);transform:none}
#pv .bar{position:absolute;left:0;bottom:0;width:100%;height:1px;background:var(--fg);transform-origin:left;transform:scaleX(0);transition:opacity .5s}
#pv .pct{position:absolute;left:.75rem;top:.75rem;font:500 .75rem/1 var(--sans);letter-spacing:.16em;font-variant-numeric:tabular-nums;transition:opacity .4s}
#pv.ready .bar,#pv.ready .pct{opacity:0}
@media(hover:none){#pv{display:none}}
/* ilustrasi: lingkar tahun kayu digambar garis tipis, lalu berputar sangat pelan */
.hero{position:relative;overflow:hidden}
.hero>*:not(.rings){position:relative;z-index:1}
.rings{position:absolute;z-index:0;right:calc(var(--g) - 5rem);top:5.5rem;width:min(64vw,44rem);aspect-ratio:1;pointer-events:none;opacity:.5;-webkit-mask-image:radial-gradient(circle,#000 50%,transparent 71%);mask-image:radial-gradient(circle,#000 50%,transparent 71%)}
.rings svg{width:100%;height:100%;display:block;animation:spin 360s linear infinite}
.rings path{fill:none;stroke:var(--fg);stroke-width:.7;stroke-linejoin:round;stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset 2.8s var(--ease);transition-delay:calc(var(--i,0)*.15s + .5s)}
.rings.in path{stroke-dashoffset:0}
.rings .crack{stroke-width:.8;opacity:.7}
@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:40rem){.rings{width:104vw;right:-34vw;top:4.5rem;opacity:.34}}
@media(prefers-reduced-motion:reduce){.rings svg{animation:none}.rings path{stroke-dashoffset:0;transition:none}}
/* ilustrasi Tentang (kiri): gambar kerja pintu 200 cm, tergambar lalu diukur */
.door{width:min(20rem,100%);margin-top:4rem}
#tentang{padding-bottom:clamp(3rem,7vw,6rem)}
.door .leaf{fill:var(--bg)}
.door .glow{fill:url(#gl);stroke:none;stroke-dasharray:none;stroke-dashoffset:0;transition:none}
.door svg{display:block;width:100%;height:auto}
.door path,.door circle{fill:none;stroke:var(--fg);stroke-width:.7;stroke-linejoin:round;stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset 2.4s var(--ease);transition-delay:calc(var(--i,0)*.2s + .4s)}
.door.in path,.door.in circle{stroke-dashoffset:0}
.door .soft{opacity:.5}
.door text{fill:var(--mute);font:500 6px var(--sans);letter-spacing:.16em;opacity:0;transition:opacity 1.2s var(--ease) 3s}
.door.in text{opacity:1}
.door .scan{stroke-dasharray:none;stroke-dashoffset:0;transition:none;opacity:0}
.door.in .scan{animation:scan 7s ease-in-out 3.4s infinite alternate}
@keyframes scan{0%{transform:translateY(10px);opacity:0}12%,88%{opacity:.85}100%{transform:translateY(214px);opacity:0}}
@media(max-width:40rem){.door{width:min(15rem,80%);margin-top:2.5rem}}
@media(max-width:55.99rem){#tentang .cols{grid-template-columns:minmax(0,clamp(5rem,24vw,12rem)) minmax(0,1fr);gap:1.25rem clamp(1.25rem,4vw,2.5rem)}#tentang .door{width:100%;margin-top:1.5rem}}
@media(max-width:30rem){.door text{display:none}}
@media(prefers-reduced-motion:reduce){.door path,.door circle{stroke-dashoffset:0;transition:none}.door text{opacity:1;transition:none}.door.in .scan{animation:none}}
ul{list-style:none;margin:0;padding:0}
.bio p{margin:0 0 1.5rem;max-width:34rem}
.bio .t{margin:0 0 2rem;max-width:22ch}
.writing .it{display:grid;gap:.4rem;padding-block:1.6rem;border-top:1px solid var(--line)}
.writing li:last-child .it{border-bottom:1px solid var(--line)}
.writing .it:hover .t,.writing .it.hv .t{font-style:italic}
.writing p{margin:0;color:var(--mute);max-width:34rem}
.contact .d a{background:linear-gradient(currentColor,currentColor) 0 100%/0 1px no-repeat;transition:background-size 1s var(--ease)}
.contact .d a:hover{background-size:100% 1px}
.contact .meta{display:flex;flex-wrap:wrap;gap:1rem 3rem;margin-top:3rem}
footer{display:flex;justify-content:space-between;gap:1rem;padding-block:2rem calc(2rem + env(safe-area-inset-bottom,0px))}
/* masuk perlahan: naik sedikit, tanpa lonjakan */
.r{opacity:0;transform:translate3d(0,22px,0);transition:opacity 1.5s var(--ease),transform 1.5s var(--ease);transition-delay:calc(var(--i,0)*110ms);will-change:opacity,transform}
.r.in{opacity:1;transform:none;will-change:auto}
@media(prefers-reduced-motion:reduce){.r{opacity:1;transform:none;transition:none}.rule{transform:none;transition:none}html{scroll-behavior:auto}}
.post-nav{padding:6rem var(--g) 0}
.post-nav a{color:var(--mute);font:500 .8125rem/1.4 var(--sans);letter-spacing:.08em;text-transform:uppercase}
.post article.post{padding:2rem var(--g) 6rem;max-width:48rem;margin-inline:auto}
.post article.post h1{font:400 clamp(2rem,5vw,3.25rem)/1.1 var(--serif);margin:0 0 2rem}
.post article.post img{max-width:100%;height:auto;border:1px solid var(--line)}

b:if.script:
//

(function(){
  var els=[].slice.call(document.querySelectorAll('.r:not(.in),.rule'));
  if(!('IntersectionObserver' in window)){els.forEach(function(e){e.classList.add('in')});return}
  var io=new IntersectionObserver(function(es){es.forEach(function(e){
    if(!e.isIntersecting)return;e.target.classList.add('in');io.unobserve(e.target)})},{threshold:.12,rootMargin:'0px 0px -8% 0px'});
  els.forEach(function(e){io.observe(e)});
})();

//

//

(function(){
  var c=document.getElementById('clk'),f=new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
  function t(){var p=f.format(new Date()).replace(/\./g,':').split(':');c.innerHTML=p[0]+':'+p[1]+'<span class="sec">:'+p[2]+'</span> <span class="tz">WIB</span>'}
  t();setInterval(t,1000);
  var root=document.documentElement,tg=document.getElementById('tg');
  function apply(m,save){root.dataset.theme=m;tg.setAttribute('aria-label',m==='light'?'Ganti ke latar gelap':'Ganti ke latar terang');if(save){try{localStorage.setItem('cmto-theme',m)}catch(e){}}}
  var s='dark';try{s=localStorage.getItem('cmto-theme')==='light'?'light':'dark'}catch(e){}
  apply(s,false);
  tg.addEventListener('click',function(){apply(root.dataset.theme==='light'?'dark':'light',true)});
})();

//

//

(function(){
  var g=document.getElementById('rg'),box=document.getElementById('rings'),out='',i,k;
  function ring(r,ph,amp){var d='',n=120,a,rr;for(k=0;k<=n;k++){a=k/n*Math.PI*2;rr=r+Math.sin(a*3+ph)*amp+Math.sin(a*5+ph*1.7)*amp*.5+Math.sin(a*2-ph)*amp*.6;d+=(k?'L':'M')+(Math.cos(a)*rr).toFixed(1)+' '+(Math.sin(a)*rr).toFixed(1)}return d+'Z'}
  for(i=0;i<14;i++)out+='<path pathLength="1" d="'+ring(8+i*13.5,i*.55,1.2+i*.28)+'" style="--i:'+i+'" opacity="'+(.9-i*.045).toFixed(2)+'"/>';
  var c='M0 0';for(k=1;k<=30;k++)c+=' L'+(k*6.2).toFixed(1)+' '+(Math.sin(k*.7)*3.2+k*.18).toFixed(1);
  out+='<path class="crack" pathLength="1" d="'+c+'" style="--i:13"/>';
  g.innerHTML=out;
  requestAnimationFrame(function(){requestAnimationFrame(function(){box.classList.add('in')})});
})();

//

//

(function(){
  if(!matchMedia('(hover:none)').matches||!('IntersectionObserver' in window))return;
  var io=new IntersectionObserver(function(es){es.forEach(function(e){
    var t=e.target;t.classList.toggle('hv',e.isIntersecting);
    var ul=t.closest('.work ul');if(ul)ul.classList.toggle('hv-on',!!ul.querySelector('a.hv'));
  })},{rootMargin:'-42% 0px -42% 0px',threshold:0});
  function bind(){[].forEach.call(document.querySelectorAll('.writing .it,.work a'),function(el){if(!el.__hv){el.__hv=1;io.observe(el)}})}
  bind();window.cmtoBindTouch=bind;
})();

//

//

(function(){
  if(!matchMedia('(hover:hover)').matches)return;
  var pv=document.getElementById('pv'),im=pv.querySelector('.im'),bar=pv.querySelector('.bar'),pct=pv.querySelector('.pct');
  var calm=matchMedia('(prefers-reduced-motion:reduce)').matches;
  var tones=[['#5b3b22','#d3a469'],['#3a2a1d','#b08a5e'],['#6a4a2b','#dcb176'],['#2d231a','#97734d']];
  function wood(i){var t=tones[i%4],p='',k,x;
    for(k=0;k<16;k++){var y=k*6.6,a=2+((k*7+i*3)%5),ph=k*.9+i;p+='<path d="M0 '+y;
      for(x=0;x<=80;x+=10)p+=' L'+x+' '+(y+Math.sin(x/12+ph)*a).toFixed(1);
      p+='" stroke="'+t[1]+'" stroke-opacity="'+(.1+((k*13)%5)*.04).toFixed(2)+'" stroke-width="'+(.3+(k%3)*.25)+'" fill="none"/>'}
    var svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 100" preserveAspectRatio="none"><rect width="80" height="100" fill="'+t[0]+'"/>'+p+'</svg>';
    return 'url("data:image/svg+xml,'+encodeURIComponent(svg)+'")'}
  var tx=0,ty=0,cx=0,cy=0,run=false,raf=0;
  function loop(){cx+=(tx-cx)*.14;cy+=(ty-cy)*.14;pv.style.transform='translate3d('+cx.toFixed(1)+'px,'+cy.toFixed(1)+'px,0)';run=pv.classList.contains('on');if(run)requestAnimationFrame(loop)}
  function aim(e){var w=pv.offsetWidth,h=pv.offsetHeight;tx=Math.min(e.clientX+28,innerWidth-w-16);ty=Math.max(8,Math.min(e.clientY-h/2,innerHeight-h-8))}
  function load(i,url){cancelAnimationFrame(raf);pv.classList.remove('ready');
    im.style.backgroundImage=url?'url("'+url+'")':wood(i);
    if(calm){bar.style.transform='scaleX(1)';pct.textContent='100%';pv.classList.add('ready');return}
    var s=performance.now();
    (function step(n){var p=Math.min((n-s)/700,1),e=1-Math.pow(1-p,3);bar.style.transform='scaleX('+e+')';pct.textContent=Math.round(e*100)+'%';
      if(p<1)raf=requestAnimationFrame(step);else pv.classList.add('ready')})(s)}
  function bind(){
    [].forEach.call(document.querySelectorAll('.work li'),function(li,i){
      var a=li.querySelector('a'),url=a?a.getAttribute('data-img'):null;
      li.addEventListener('mouseenter',function(e){aim(e);if(!pv.classList.contains('on')){cx=tx;cy=ty}pv.classList.add('on');load(i,url);if(!run){run=true;requestAnimationFrame(loop)}});
      li.addEventListener('mousemove',aim);
      li.addEventListener('mouseleave',function(){pv.classList.remove('on')});
    });
  }
  bind();
  window.cmtoBindPreview=bind;
})();

//

//

(function(){
  var list=document.getElementById('karya-list');
  if(!list)return;
  var WA='6287847644244';
  function esc(s){return String(s==null?'':s).replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})}
  fetch('https://cdn.jsdelivr.net/gh/woodroker/cmto@main/data/products.json',{cache:'no-store'})
    .then(function(r){if(!r.ok)throw new Error(r.status);return r.json()})
    .then(function(items){
      if(!Array.isArray(items)||!items.length)return;
      var max=8;
      var picked=items.slice(0,max);
      list.innerHTML=picked.map(function(p,i){
        var num=String(i+1).length<2?'0'+(i+1):(i+1);
        var wa='https://wa.me/'+WA+'?text='+encodeURIComponent('Halo CMTO, saya tertarik dengan '+(p.name||'')+'. Apakah tersedia?');
        return '<li class="r in"><a href="'+wa+'" target="_blank" rel="noopener" data-img="'+esc(p.image)+'">'
          +'<span class="n">'+num+'</span><span class="t">'+esc(p.name)+'</span><span class="m">'+esc(p.category)+'</span></a></li>';
      }).join('');
      picked.forEach(function(p){if(p.image){var im=new Image();im.src=p.image}});
      if(window.cmtoBindPreview)window.cmtoBindPreview();
      if(window.cmtoBindTouch)window.cmtoBindTouch();
    })
    .catch(function(){ /* biarkan fallback statis */ });
})();

//
